-- =============================================================================
-- Catálogo de puzzles de Neon Sudoku Matrix (`public.sudoku_puzzles`).
--
-- Réplica en la nube del banco de puzzles que el cliente KMP también trae
-- empaquetado como seed offline (`composeResources/files/sudoku_bank.csv`). El
-- cliente lo usa para ENRIQUECER su caché local con más variedad cuando hay
-- sesión (ver SudokuPuzzleRepositoryImpl / RemoteSudokuPuzzleDataSource); nunca
-- escribe aquí. Por eso es un CATÁLOGO de solo lectura, igual que `games`:
-- lectura para `authenticated`, escritura solo vía `service_role` (esta
-- migración). El invitado offline no lo necesita: se sirve del seed empaquetado.
--
-- Los puzzles se generan y RATEAN por técnica offline con
-- `tools/sudoku/generate_bank.py` (solución única garantizada por backtracking).
-- Archivo nuevo e idempotente: no reescribe migraciones ya aplicadas y se puede
-- re-ejecutar sin efecto (ON CONFLICT DO NOTHING).
-- =============================================================================

create table if not exists public.sudoku_puzzles (
    id          uuid        primary key,
    -- Ordinal de SudokuDifficulty en el cliente: 0=FACIL,1=MEDIO,2=DIFICIL,3=EXPERTO.
    difficulty  smallint    not null check (difficulty between 0 and 3),
    -- 81 caracteres fila a fila: dígitos 1-9 son pistas, '0' celda vacía.
    puzzle      text        not null check (char_length(puzzle) = 81),
    -- Solución completa (81 dígitos 1-9), única. Habilita pistas/verificación futura.
    solution    text        not null check (char_length(solution) = 81),
    created_at  timestamptz not null default now()
);

comment on table public.sudoku_puzzles is
    'Catálogo de puzzles de Neon Sudoku Matrix, rateados por técnica offline. Solo lectura para clientes; enriquece la cache local del juego.';

-- El cliente filtra por dificultad (RemoteSudokuPuzzleDataSource); el indice evita
-- escanear toda la tabla en esa consulta.
create index if not exists sudoku_puzzles_difficulty_idx
    on public.sudoku_puzzles (difficulty);

alter table public.sudoku_puzzles enable row level security;

-- Catalogo de solo lectura para usuarios autenticados (mismo patron que `games`,
-- ver 0002_rls_policies.sql). La escritura la hace esta migracion como service_role.
create policy "sudoku_puzzles_read_all"
    on public.sudoku_puzzles for select
    to authenticated
    using (true);

on conflict (id) do nothing;
